import{_ as t,c as s,o as a,ah as o}from"./chunks/framework.l36K22_3.js";const p="/assets/SLR_twelfth1.D7Dp0UV2.jpeg",i="data:image/jpeg;base64,",e="data:image/jpeg;base64,",l="/assets/SLR_twelfth4.DN5OQj8x.jpeg",n="/assets/SLR_twelfth5.BT6TTSXv.jpeg",r="/assets/SLR_twelfth6.h2K15mAV.jpeg",B="/assets/SLR_twelfth7.hBJtpDJi.jpeg",m="/assets/SLR_twelfth8.BZhtf6FC.jpeg",L=JSON.parse('{"title":"“直方图(histogram)” - 单反入门第十二课","description":"在一些高档消费级数码相机上有很多实用功能，现在的 DSLR 在使用机背 LCD 预览照片时，有额外显示直方图（histogram）的功能，这个功能可以帮助我们利用阶调分布的图形，来观察一张照片明暗分布的比例状况。 直方图是通过在 LCD 上...","frontmatter":{"title":"“直方图(histogram)” - 单反入门第十二课","date":"2012-09-15T00:00:00.000Z","category":"photo","tags":["单反教程"],"slug":"introduction-to-SLR-twelfth","layout":"blog-post","description":"在一些高档消费级数码相机上有很多实用功能，现在的 DSLR 在使用机背 LCD 预览照片时，有额外显示直方图（histogram）的功能，这个功能可以帮助我们利用阶调分布的图形，来观察一张照片明暗分布的比例状况。 直方图是通过在 LCD 上..."},"headers":[],"relativePath":"blog/introduction-to-SLR-twelfth.md","filePath":"blog/posts/photo/introduction-to-SLR-twelfth.md","lastUpdated":1788854523000}'),S={name:"blog/introduction-to-SLR-twelfth.md"};function g(z,A,O,R,c,D){return a(),s("div",null,A[0]||(A[0]=[o('<p>在一些高档消费级数码相机上有很多实用功能，现在的 DSLR 在使用机背 LCD 预览照片时，有额外显示直方图（histogram）的功能，这个功能可以帮助我们利用阶调分布的图形，来观察一张照片明暗分布的比例状况。</p><p>直方图是通过在 LCD 上显示出来的波形参数来确定照片曝光精度的工具，现在许多高档相机在取景的时候就能够看见实时直方图，这在拍摄时是非常好的帮手。通过直方图的横轴和纵轴我们可以清楚地来判断拍摄的照片或者正在取景的照片曝光情况。</p><p>我们知道，数码相机相对于传统胶片相机一个很大的优势就是即拍即现，拍出的照片立刻就能在 LCD 液晶屏上回放看到效果。不过现在的数码相机动辄就是 400 万以上像素，而这些相机所配备的 LCD 液晶屏往往只有十几万像素，因此这个小小的 LCD 液晶屏根本不能完全表现出所拍照片的细节效果。特别是因为 LCD 对于光线并不那么敏感，很多时候拍摄的照片即使过曝或者曝光不足通过 LCD 也难以反映出来，这里我们就要借助许多数码相机内置的―直方图显示‖功能来判断拍摄的相片曝光是否均匀。</p><p>首先来看一下 histogram 的阅读方式。在画面的水平轴，代表的是画面的明暗部，越靠左边越暗、越往右边则越亮，也就是说，整个画面的明调在右手的方向、暗调在左手的方向，而中间调则是位于中间的部位。一幅比较好的图应该明暗细节都有，在柱状图上就是从左到右都有分布，同时直方图的两侧是不会有像素溢出的。而直方图的竖轴就表示相应部分所占画面的面积，峰值越高说明该明暗值的像素数量越多。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>如果直方图显示只在左边有，说明画面没有明亮的部分，整体偏暗，有可能曝光不足</p><p><img src="'+i+'" alt="" loading="lazy"></p><p>而如果直方图显示只在右边有，说明画面缺乏暗部细节，很有可能曝光过度</p><p><img src="'+e+'" alt="" loading="lazy"></p><p>在 histogram 垂直轴的部分，代表的是该区域像素分布数目的多寡，越低像素越少、越高像素就会越多。从水平轴跟垂直轴的分布，我们就可以大致的看出一张照片它的明暗分布大约是甚么样的状况。</p><p>下面来看一下各种不同照片的直方图。 <img src="'+l+'" alt="" loading="lazy"></p><p>像素集中在明调的区域，明显的曝光过渡了</p><p><img src="'+n+'" alt="" loading="lazy"></p><p>像素平均的分配在每个区域，曝光良好</p><p><img src="'+r+'" alt="" loading="lazy"></p><p>像都集中到暗部去了，曝光不足</p><p>一般来说，一张曝光良好的照片，它的 histogram 分配应该是明暗部相当平均的，这样整个画面的明暗比例才会适切。但有时如果我们要拍一些亮调子（所谓的 high key）或者是暗调子（所谓的 low key）的照片，反而就需要调整一下明暗分布的比重了。</p><p><img src="'+B+'" alt="" loading="lazy"></p><p>这是暗调子的拍摄手法，用来表现阴郁的感觉</p><p><img src="'+m+'" alt="" loading="lazy"></p><p>这是亮调子的拍摄手法，画面看来清爽而明亮</p><p>直方图可以用来帮助我们了解曝光的好坏多寡，以及照片的拍摄调性。有许多新手在使用 DSLR 时都会去忽略了这个功能，其实是蛮可惜的一件事情。记得下次在拍照时，多多利用一下 histogram 来观察相片的明暗，这样可以增进我们对曝光抓取的敏感跟准确度喔。</p><p>直方图能够显示曝光不足的问题，这样玩家就可以进行曝光补偿调节，在数码相机上这个过程可以很直观快速地反映出来，最后的效果我们也可以立刻看到。除此之外，直方图还能够显示曝光过度的问题，我们可以进行相应的负补偿，相机通过缩小光圈或者提高快门速度来减少曝光。曝光补偿是在测光系统难以做出准确判断的时候的一个调整手段，有些物体和景物是很难通过测光系统进行准确曝光处理的，例如雪景，通常都会造成曝光不足，此时要遵守白加黑减的曝光补偿原则，一般就能拍摄出曝光准确的照片。而对于有实时直方图的机器，我们在拍摄之前通过直方图信息，就可以大概知道该幅照片的曝光情况，节省了拍摄中宝贵的时间。 <br></p>',23)]))}const I=t(S,[["render",g]]);export{L as __pageData,I as default};
